package com.tamo.service;
import com.google.gson.*;
import com.tamo.model.*;
import com.tamo.util.JsonUtil;
import java.util.*;
public class ReviewService{
 private final JsonDataService data;public ReviewService(JsonDataService data){this.data=data;}
 public static boolean approved(DataStore ds,String app){ReviewRecord latest=null;for(ReviewRecord r:ds.getReviewRecords())if(app.equals(r.getApplicationId())&&Set.of("approve","not_selected").contains(r.getAction()))latest=r;return latest!=null&&"approve".equals(latest.getAction());}
 public static boolean approvedForSection(DataStore ds,String app,String section){ReviewRecord latest=null;for(ReviewRecord r:ds.getReviewRecords())if(app.equals(r.getApplicationId())&&Set.of("approve","not_selected").contains(r.getAction()))latest=r;return latest!=null&&"approve".equals(latest.getAction())&&(latest.getSectionId()==null||latest.getSectionId().equals(section));}
 private Application application(String id){return data.getData().getApplications().stream().filter(a->Objects.equals(id,a.getId())).findFirst().orElseThrow(()->new QualificationService.Problem(404,"Application not found."));}
 private Job job(Application a){return data.getData().getJobs().stream().filter(j->Objects.equals(a.getJobId(),j.getId())).findFirst().orElseThrow(()->new QualificationService.Problem(404,"Position not found."));}
 private void check(User u,Application a){Job j=job(a);if(!ReviewAccess.can(u,"review.read")||data.getData().getModules().stream().noneMatch(m->Objects.equals(j.getModuleId(),m.getId())&&ReviewAccess.course(u,m)))throw new QualificationService.Problem(403,"Review access is not granted for this course.");}
 public JsonObject row(User u,Application a){check(u,a);Job j=job(a);DataStore ds=data.getData();JsonObject r=new JsonObject();TeacherSelectionService.addCapabilities(r,ds,u,a);r.addProperty("id",a.getId());r.addProperty("periodId",a.getPeriodId());r.addProperty("moduleId",j.getModuleId());r.addProperty("moduleCode",j.getModuleCode());
  r.addProperty("name",a.getQualificationSnapshot()!=null&&a.getQualificationSnapshot().has("fullName")?a.getQualificationSnapshot().get("fullName").getAsString():ds.getUsers().stream().filter(x->Objects.equals(x.getId(),a.getApplicantId())).map(User::getName).findFirst().orElse("Historical applicant"));
  r.addProperty("applicationStatus",RecruitmentStatus.current(a.getStatus()));r.addProperty("appliedAt",a.getAppliedAt());r.add("qualifications",a.getQualificationSnapshot()==null?new JsonObject():a.getQualificationSnapshot().deepCopy());r.add("matching",new CriteriaMatchingService().evaluateAcrossSections(ds,a,j));r.add("scheduleMatching",new SectionMatchingService().match(ds,a,j,ReviewAccess.currentOrganiser(ds,j)));
  String state="under_consideration";for(ReviewRecord v:ds.getReviewRecords())if(a.getId().equals(v.getApplicationId())&&Set.of("recommend","alternate","approve","not_selected","flag").contains(v.getAction()))state=v.getAction();ReviewRecord decision=null;for(ReviewRecord v:ds.getReviewRecords())if(a.getId().equals(v.getApplicationId())&&Set.of("approve","not_selected").contains(v.getAction()))decision=v;
  r.addProperty("selectionStatus",decision==null?state:"approve".equals(decision.getAction())?"selected":"not_selected");
  for(String p:List.of("note","recommend","approve"))r.addProperty("can"+Character.toUpperCase(p.charAt(0))+p.substring(1),ReviewAccess.can(u,"review."+p));
  boolean internal=ReviewAccess.can(u,"review.note")||ReviewAccess.can(u,"review.recommend")||ReviewAccess.can(u,"review.approve");if(internal)r.add("records",JsonUtil.getGson().toJsonTree(ds.getReviewRecords().stream().filter(v->a.getId().equals(v.getApplicationId())).toList()));return r;
 }
 public JsonObject list(String id,Map<String,String> filters){User u=ReviewAccess.user(data.getData(),id);if(!ReviewAccess.can(u,"review.read"))throw new QualificationService.Problem(403,"Review permission required.");JsonArray rows=new JsonArray();List<JsonObject> list=new ArrayList<>();for(Application a:data.getData().getApplications())try{JsonObject r=row(u,a);if(matches(r,filters))list.add(r);}catch(QualificationService.Problem e){if(e.status!=403)throw e;}
  String sort=filters.getOrDefault("sort","newest");list.sort((a,b)->"name".equals(sort)?a.get("name").getAsString().compareToIgnoreCase(b.get("name").getAsString()):"score".equals(sort)?Double.compare(score(b),score(a)):string(b,"appliedAt").compareTo(string(a,"appliedAt")));list.forEach(rows::add);JsonObject result=new JsonObject();result.add("applications",rows);result.add("periods",JsonUtil.getGson().toJsonTree(data.getData().getApplicationPeriods()));result.add("modules",JsonUtil.getGson().toJsonTree(data.getData().getModules().stream().filter(m->ReviewAccess.course(u,m)).toList()));return result;
 }
 private String string(JsonObject value,String key){JsonElement v=value.get(key);return v==null||v.isJsonNull()?"":v.getAsString();}
 private double score(JsonObject r){JsonElement v=r.getAsJsonObject("matching").get("score");return v==null||v.isJsonNull()?-1:v.getAsDouble();}
 private boolean matches(JsonObject r,Map<String,String> f){JsonObject q=r.getAsJsonObject("qualifications");for(String key:List.of("periodId","moduleId","selectionStatus"))if(f.containsKey(key)&&!f.get(key).isBlank()&&!f.get(key).equals(r.get(key).getAsString()))return false;
  if(f.containsKey("level")&&!f.get("level").isBlank()&&(!q.has("studentLevel")||!f.get("level").equals(q.get("studentLevel").getAsString())))return false;
  for(String[] field:new String[][]{{"skill","skills"},{"interest","interests"}})if(f.containsKey(field[0])&&!f.get(field[0]).isBlank()){boolean found=false;if(q.has(field[1]))for(JsonElement term:q.getAsJsonArray(field[1]))if(term.getAsString().toLowerCase(Locale.ROOT).contains(f.get(field[0]).toLowerCase(Locale.ROOT)))found=true;if(!found)return false;}
  if(f.containsKey("experience")&&!f.get("experience").isBlank()){boolean has=q.has("teachingExperience")&&!q.get("teachingExperience").getAsString().isBlank();if(has!=f.get("experience").equals("yes"))return false;}
  if(f.containsKey("match")&&!f.get("match").isBlank()&&!f.get("match").equals(r.getAsJsonObject("matching").get("status").getAsString()))return false;
  return !f.containsKey("search")||r.get("name").getAsString().toLowerCase(Locale.ROOT).contains(f.get("search").toLowerCase(Locale.ROOT));
 }
 public JsonObject record(String user,String appId,JsonObject body){DataStore ds=data.getData();User u=ReviewAccess.user(ds,user);Application a=application(appId);check(u,a);String action=QualificationService.text(body,"action",30,true),note=QualificationService.text(body,"note",4000,true);
  String permission=switch(action){case "note","flag"->"review.note";case "recommend","alternate"->"review.recommend";case "approve","not_selected"->"review.approve";default->throw new QualificationService.Problem(400,"Unknown review action.");};if(!ReviewAccess.can(u,permission))throw new QualificationService.Problem(403,"This action requires "+permission);
  if(Set.of("approve","not_selected").contains(action)&&note.length()<10)throw new QualificationService.Problem(400,"Record a decision reason of at least 10 characters.");
  if("not_selected".equals(action)&&SectionAssignmentService.activeForApplication(ds,appId))throw new QualificationService.Problem(409,"Cancel active assignments before changing the selection decision.");
  ReviewRecord record=new ReviewRecord();record.setId("review_"+UUID.randomUUID().toString().replace("-",""));record.setApplicationId(appId);record.setActorId(user);record.setAction(action);record.setNote(note);record.setCreatedAt(java.time.Instant.now().toString());Job j=job(a);record.setCriteriaSnapshot(new CriteriaMatchingService().evaluateAcrossSections(ds,a,j));record.setScheduleSnapshot(new SectionMatchingService().match(ds,a,j,ReviewAccess.currentOrganiser(ds,j)));
  if(body.has("sectionId")&&!body.get("sectionId").getAsString().isBlank()){String sectionId=body.get("sectionId").getAsString();CourseSection section=ds.getCourseSections().stream().filter(s->JobSectionService.includes(j,s)&&sectionId.equals(s.getId())&&Objects.equals(s.getModuleId(),j.getModuleId())&&Objects.equals(s.getPeriodId(),a.getPeriodId())).findFirst().orElseThrow(()->new QualificationService.Problem(400,"Choose a section in this course and cycle."));record.setSectionId(sectionId);record.setCriteriaSnapshot(new CriteriaMatchingService().evaluate(a,j,section));}
  ds.getReviewRecords().add(record);if("approve".equals(action))a.setStatus("offer");if("not_selected".equals(action))a.setStatus("rejected");a.setUpdatedAt(record.getCreatedAt());data.save();data.addLog("Application Review "+action,"info",u.getName(),u.getId(),"Recorded "+action+" for application "+appId,"127.0.0.1");return row(u,a);
 }
}
